#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>

#define RST_PIN 9
#define SS_PIN 10
MFRC522 mfrc522(SS_PIN, RST_PIN);
Servo lockServo;

byte masterUID[4] = {0xDE, 0xAD, 0xBE, 0xEF}; // Replace with your card UID

void setup() {
  Serial.begin(9600);
  SPI.begin();
  mfrc522.PCD_Init();
  lockServo.attach(6);
  lockServo.write(0); // Locked
}

void loop() {
  if (!mfrc522.PICC_IsNewCardPresent() || !mfrc522.PICC_ReadCardSerial()) return;

  bool match = true;
  for (byte i = 0; i < 4; i++) {
    if (mfrc522.uid.uidByte[i] != masterUID[i]) match = false;
  }

  if (match) {
    lockServo.write(90); // Unlock
    delay(3000);
    lockServo.write(0);  // Re-lock
  }
  mfrc522.PICC_HaltA();
}
